from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrrelParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.nrrel_ent = self.enb_ent_config['cells'][self.cell_num]['nrrel'][self.mo_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mcc, mnc = self.nrrel_ent['mcc'], self.nrrel_ent['mnc']

        self.set_struct_parameter('gnbPlmn', [
            {
                'mcc': mcc,
                'mnc': mnc,
                'mncLength': self.get_len_str(mnc),
            }
        ])
        self.set_parameter('gNbId', self.nrrel_ent['gnb_id'])
        self.set_parameter('lcrId', self.nrrel_ent['lcr_id'])
